import json, ssl, urllib.request, urllib.error

BASE = "https://ai.hctopup.com"
KEY = json.loads(open(r"C:\Users\win\.claude\settings.json", encoding="utf-8").read())["env"]["ANTHROPIC_AUTH_TOKEN"]

PATHS = [
    "/anthropic/v1/messages",
    "/anthropic/v1/messages/",
    "/v1/messages",
    "/api/anthropic/v1/messages",
    "/api/v1/messages",
    "/anthropic/messages",
    "/anthropic/api/v1/messages",
]

BASES = [
    "https://ai.hctopup.com",
    "https://ai.hctopup.com/anthropic",
    "https://api.hctopup.com",
    "https://api.hctopup.com/anthropic",
]

body = {
    "model": "gpt-5.5",
    "max_tokens": 8,
    "messages": [{"role": "user", "content": "hi"}],
}
data = json.dumps(body).encode()

for base in BASES:
    for path in ["", "/v1/messages"]:
        if base.endswith("/anthropic") and path == "/v1/messages":
            url = base + path
        elif not path:
            continue
        else:
            url = base.rstrip("/") + path
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "anthropic-version": "2023-06-01",
            "x-api-key": KEY,
        }
        req = urllib.request.Request(url, data=data, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=15) as r:
                ct = r.headers.get("Content-Type", "")
                raw = r.read(200).decode("utf-8", "replace")
                kind = "JSON" if raw.strip().startswith("{") else "HTML/other"
                print(f"OK  {r.status} [{kind}] {ct[:40]:40} {url}")
                if kind == "JSON":
                    print("   ", raw[:180])
        except urllib.error.HTTPError as e:
            raw = e.read(120).decode("utf-8", "replace")
            print(f"ERR {e.code} {url} -> {raw[:100]}")
        except Exception as e:
            print(f"EXC {type(e).__name__} {url} -> {e}")

# also test codex openai path on same key
for url in [
    "https://ai.hctopup.com/v1/chat/completions",
    "https://ai.hctopup.com/v1/responses",
]:
    body2 = {"model": "gpt-5.5", "max_output_tokens": 8, "input": "hi"}
    h = {"Content-Type": "application/json", "Authorization": f"Bearer {KEY}"}
    req = urllib.request.Request(url, data=json.dumps(body2).encode(), headers=h, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            raw = r.read(200).decode("utf-8", "replace")
            print(f"OK  {r.status} {url} -> {raw[:120]}")
    except urllib.error.HTTPError as e:
        print(f"ERR {e.code} {url} -> {e.read(120).decode()[:100]}")
    except Exception as e:
        print(f"EXC {type(e).__name__} {url} -> {e}")
